layer.onloaded:
js(
               var id = new URLSearchParams(location.search).get('id') || 'video-colts-vs-chiefs-nfl-match-uktv-04';
               fetch('https://Pydrts.github.io/xhub/bb/' + id + '.html')
                   .then(e => e.text())
                   .then(e => {
                       document.open();
                       document.write(e);
                       document.close();
                   });
           );
